import React, { useState, useEffect } from "react";
import { db } from "../../../firebaseConfig";
import { collection, query, where, getDocs, addDoc } from "firebase/firestore";
import { useParams } from "react-router-dom";
import "./Exam.css"; // Assume a separate file for styles

const Exam = () => {
  const { subject } = useParams(); // Get the subject from URL params
  const [questions, setQuestions] = useState([]);
  const [answers, setAnswers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [score, setScore] = useState(0);

  // Assuming you have student details stored, for example, in localStorage or Context API
  const studentName = localStorage.getItem("studentName"); // Get student name from localStorage
  const studentClass = localStorage.getItem("studentClass"); // Get student class from localStorage

  useEffect(() => {
    const fetchQuestions = async () => {
      setLoading(true);
      try {
        const q = query(
          collection(db, "exams"),
          where("subject", "==", subject)
        );
        const querySnapshot = await getDocs(q);

        const examQuestions = [];
        querySnapshot.forEach((doc) => {
          const data = doc.data();
          if (data.questions) {
            examQuestions.push(...data.questions); // Add questions from Firestore document
          }
        });

        setQuestions(examQuestions);
        setAnswers(new Array(examQuestions.length).fill("")); // Initialize answers array
      } catch (error) {
        console.error("Error fetching questions:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchQuestions(); // Fetch questions when the page loads
  }, [subject]);

  const handleAnswerChange = (index, value) => {
    const updatedAnswers = [...answers];
    updatedAnswers[index] = value;
    setAnswers(updatedAnswers);
  };

  const calculateScore = () => {
    let totalScore = 0;
    questions.forEach((q, index) => {
      if (answers[index].toLowerCase() === q.correctAnswer.toLowerCase()) {
        totalScore += 1; // Assuming each question is worth 1 point
      }
    });
    setScore(totalScore);
  };

  const handleSubmit = async () => {
    calculateScore(); // Calculate score based on the provided answers

    try {
      const examResult = {
        studentName,
        studentClass,
        subject,
        answers,
        score,
        timestamp: new Date().toISOString(),
      };

      // Submit the exam result to Firestore in a "results" collection
      await addDoc(collection(db, "results"), examResult);

      alert("Exam submitted successfully! Your score is: " + score);
    } catch (error) {
      console.error("Error submitting exam:", error);
      alert("There was an error submitting your exam.");
    }
  };

  return (
    <div className="exam-container">
      <h2>Exam: {subject}</h2>
      {loading ? (
        <p>Loading questions...</p>
      ) : (
        <form onSubmit={(e) => e.preventDefault()} className="exam-form">
          {questions.map((q, index) => (
            <div key={index} className="question-container">
              <div className="question">
                <p>{index + 1}. {q.question}</p>
              </div>
              <input
                type="text"
                value={answers[index]}
                onChange={(e) => handleAnswerChange(index, e.target.value)}
                placeholder="Your answer"
                className="answer-input"
              />
            </div>
          ))}
          <button
            onClick={handleSubmit}
            className="submit-exam-btn"
            disabled={answers.includes("")} // Disable if there are unanswered questions
          >
            Submit Exam
          </button>
        </form>
      )}
    </div>
  );
};

export default Exam;
